// Seleciona os leads cuja hora de envio chegou e resolve o bot de cada mensagem.
// O campo "Mensagem enviada em" funciona como trava: lead já disparado não volta.
const BOT_POR_MENSAGEM = {
  "01 | Boas-vindas (primeiro contato)": 13352,
  "02 | Retorno fora do horário": 13212,
  "03 | Apresentação da clínica + método": 13354,
  "04 | Qualificação (perguntas iniciais)": 13216,
  "05 | Convite para agendar consulta": 13218,
  "06 | Endereço + como chegar": 13356,
  "07 | Confirmação de agendamento": 13358,
  "08 | Lembrete véspera da consulta": 13360,
  "09 | Confirmação no dia (2h antes)": 13362,
  "10 | No-show (faltou consulta)": 13134,
  "11 | Objeção: 'vou operar'": 13364,
  "12 | Objeção: preço": 13226,
  "13 | Follow-up 'vou pensar'": 13124,
  "14 | Reativação de lead frio": 13130,
  "15 | Pedido de avaliação Google / NPS": 13366,
  "16 | Autoridade + método (Cialdini)": 13368,
  "17 | Prova social - depoimento em vídeo": 13126,
  "18 | Escassez - últimos horários": 13370,
  "19 | Escassez - campanha do mês": 13372,
  "20 | PAS - amplificação de dor": 13374,
  "21 | Loss aversion - custo de adiar": 13128,
  "22 | Yes-ladder - ligação de 5 min": 13228,
  "23 | Objeção: 'vou conversar com esposo(a)'": 13376,
  "24 | Objeção: não moro em Boa Vista": 13378,
  "25 | Objeção: 'vou esperar melhorar'": 13380,
  "26 | Objeção: 'já fiz fisio e não deu certo'": 13382,
  "27 | Anchoring - cirurgia vs tratamento": 13384,
  "28 | Reciprocidade - conteúdo grátis": 13386,
  "29 | Storytelling - caso real de paciente": 13388,
  "30 | Break-up (última mensagem - Kennedy)": 13390
};
const F_QUANDO = 496166, F_QUAL = 496168, F_ENVIADO = 496170;
const agora = Math.floor(Date.now() / 1000);
const saida = [];

for (const item of $input.all()) {
  for (const lead of (item.json?._embedded?.leads ?? [])) {
    const cfs = lead.custom_fields_values ?? [];
    const val = (id) => cfs.find((c) => c.field_id === id)?.values?.[0]?.value ?? null;

    const quando = Number(val(F_QUANDO) ?? 0);
    const mensagem = val(F_QUAL);
    const jaEnviado = val(F_ENVIADO);

    if (!quando || quando > agora) continue;   // ainda não chegou a hora
    if (!mensagem) continue;                    // sem mensagem escolhida
    if (jaEnviado) continue;                    // trava de reenvio

    const botId = BOT_POR_MENSAGEM[mensagem];
    if (!botId) {                               // opção sem bot: avisa em vez de silenciar
      saida.push({ json: { erro: 'sem bot para a mensagem', leadId: lead.id, mensagem } });
      continue;
    }
    saida.push({ json: { leadId: lead.id, botId, mensagem, agendadoPara: quando } });
  }
}
return saida;
